//! ircnext: a modern IRC client with IRCv3 support.

// No console window behind the application on Windows.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod app;
mod buffer;
mod certificate;
mod completion;
mod config;
mod i18n;
mod ignore;
mod input;
mod keychain;
mod keymap;
mod log;
mod notify;
mod secrets;
mod server;
mod settings;
mod suggest;
mod theme;
mod transfer;
mod ui;

use app::App;

/// Window icon, 128 × 128 straight RGBA (generated by `tools/icons`).
const WINDOW_ICON: &[u8] = include_bytes!("../../../assets/icon/ircnext-128.rgba");

fn main() -> iced::Result {
    iced::application(App::boot, App::update, App::view)
        .title(App::title)
        .theme(App::theme)
        .subscription(App::subscription)
        .window(iced::window::Settings {
            size: iced::Size::new(1200.0, 780.0),
            position: iced::window::Position::Centered,
            // macOS takes the icon of the application bundle instead.
            icon: iced::window::icon::from_rgba(WINDOW_ICON.to_vec(), 128, 128).ok(),
            ..iced::window::Settings::default()
        })
        .antialiasing(true)
        .run()
}
